import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// xtmd-android-runtime: Extended Mark's native runtime for Android, and its Kotlin bindings (generated by
// UniFFI, with the runtime built for Android's processors, by ./rust/build.sh into native/). It
// draws nothing.
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
    `maven-publish`
}

val native = layout.projectDirectory.dir("native")

android {
    namespace = "xtmd.android.ffi"
    compileSdk = 36
    // the build tools and NDK this box has (README): AGP would otherwise fetch its own defaults
    buildToolsVersion = "36.1.0"
    ndkVersion = "30.0.16248370"
    defaultConfig {
        minSdk = 26
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    sourceSets {
        getByName("main") {
            // uniffi-bindgen's xtmd/android/ffi/xtmd_android.kt, and libxtmd_android.so per processor
            java.srcDir(native.dir("kotlin"))
            jniLibs.srcDir(native.dir("jniLibs"))
        }
    }
    lint { abortOnError = false }
    publishing { singleVariant("release") { withSourcesJar() } }
}

afterEvaluate {
    publishing {
        publications {
            create<MavenPublication>("release") {
                from(components["release"])
                groupId = "xtmd"
                artifactId = "xtmd-android-runtime"
                version = "0.4.0"
            }
        }
        repositories { maven { url = uri(rootProject.layout.buildDirectory.dir("repo")) } }
    }
}

kotlin { compilerOptions { jvmTarget.set(JvmTarget.JVM_17) } }

dependencies {
    implementation("${libs.jna.aar.get()}@aar")
}

// The native libraries and bindings must be there before anything compiles.
val nativeThere = tasks.register("checkNative") {
    val bindings = native.file("kotlin/xtmd/android/ffi/xtmd_android.kt").asFile
    doLast {
        if (!bindings.exists()) throw GradleException("no bindings in ${bindings.parent}: run runtime/kotlin/rust/build.sh first (README.md)")
    }
}
tasks.named("preBuild") { dependsOn(nativeThere) }
